module.exports = "<ion-header class=\"interior-header\">\r\n  <app-loading></app-loading>\r\n  <app-page-header titleKey=\"pageHeader.auth/account/account\" fallback=\"/\">\r\n\r\n  </app-page-header>\r\n</ion-header>\r\n\r\n<ion-content [fullscreen]=\"true\" class=\"account-content\">\r\n  <main class=\"account-page\" [attr.dir]=\"language.direction\">\r\n    <!-- Ambient educational glow accents -->\r\n    <div class=\"ambient ambient-purple\" aria-hidden=\"true\"></div>\r\n    <div class=\"ambient ambient-amber\" aria-hidden=\"true\"></div>\r\n    <div class=\"ambient ambient-emerald\" aria-hidden=\"true\"></div>\r\n\r\n    <!-- Decorative floating stationery doodles -->\r\n    <div class=\"decor-star star-1\" aria-hidden=\"true\">✦</div>\r\n    <div class=\"decor-star star-2\" aria-hidden=\"true\">★</div>\r\n    <div class=\"decor-circle circle-1\" aria-hidden=\"true\"></div>\r\n    <div class=\"decor-circle circle-2\" aria-hidden=\"true\"></div>\r\n\r\n    <section class=\"account-shell\">\r\n      <!-- Showcase panel (educational hero panel) -->\r\n      <aside class=\"experience-panel\" [attr.aria-label]=\"'account.benefits' | translate\">\r\n        <div class=\"panel-decor-glow\" aria-hidden=\"true\"></div>\r\n\r\n        <div class=\"brand-row avalamooz-brand\">\r\n          <div class=\"brand-mark avalamooz-logo-frame\">\r\n            <img width=\"144\" height=\"44\" class=\"avalamooz-logo\" src=\"./assets/learning/brand/logo.png\" alt=\"اول آموز\" />\r\n            <span class=\"sparkle-tag\" aria-hidden=\"true\">✦</span>\r\n          </div>\r\n          <div class=\"brand-text\">\r\n            <strong>{{ 'brand.name' | translate }}</strong>\r\n            <span>{{ 'account.academy' | translate }}</span>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"hero-copy\">\r\n          <div class=\"eyebrow-chip\">\r\n            <span class=\"chip-star\">✦</span>\r\n            <span>{{ 'account.heroEyebrow' | translate }}</span>\r\n          </div>\r\n          <h1>\r\n            {{ 'account.heroLead' | translate }}<br />\r\n            <span class=\"gradient-lead\">{{ 'account.heroHighlight' | translate }}</span>\r\n            {{ 'account.heroEnd' | translate }}\r\n          </h1>\r\n          <p>{{ 'account.heroDescription' | translate }}</p>\r\n        </div>\r\n\r\n        <!-- Centerpiece Educational Illustration -->\r\n        <div class=\"showcase-art\" aria-hidden=\"true\">\r\n          <div class=\"illustration-wrap\">\r\n            <img class=\"hero-art-img\" src=\"./assets/learning/learning-kit.svg\" alt=\"ملزومات کلاسی اول آموز\" />\r\n          </div>\r\n\r\n          <!-- Floating Badges -->\r\n          <div class=\"floating-pill pill-top\">\r\n            <div class=\"pill-icon icon-purple\">\r\n              <ion-icon name=\"ribbon-outline\"></ion-icon>\r\n            </div>\r\n            <div class=\"pill-text\">\r\n              <strong>ویژه پایه اول دبستان</strong>\r\n              <small>روش تدریس الفبا و ریاضی</small>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"floating-pill pill-bottom\">\r\n            <div class=\"pill-icon icon-emerald\">\r\n              <ion-icon name=\"checkmark-done-circle-outline\"></ion-icon>\r\n            </div>\r\n            <div class=\"pill-text\">\r\n              <strong>+۱۲۰ ساعت دوره تخصصی</strong>\r\n              <small>منطبق با کتب درسی رسمی</small>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Benefits Grid -->\r\n        <div class=\"benefits-grid\">\r\n          <div class=\"benefit-card\">\r\n            <div class=\"benefit-icon icon-purple\">\r\n              <ion-icon name=\"infinite-outline\"></ion-icon>\r\n            </div>\r\n            <div class=\"benefit-body\">\r\n              <strong>{{ 'account.lifetimeAccess' | translate }}</strong>\r\n              <small>{{ 'account.toPurchasedCourses' | translate }}</small>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"benefit-card\">\r\n            <div class=\"benefit-icon icon-amber\">\r\n              <ion-icon name=\"people-outline\"></ion-icon>\r\n            </div>\r\n            <div class=\"benefit-body\">\r\n              <strong>{{ 'account.community' | translate }}</strong>\r\n              <small>{{ 'account.learnTogether' | translate }}</small>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"benefit-card\">\r\n            <div class=\"benefit-icon icon-emerald\">\r\n              <ion-icon name=\"shield-checkmark-outline\"></ion-icon>\r\n            </div>\r\n            <div class=\"benefit-body\">\r\n              <strong>{{ 'account.securePayment' | translate }}</strong>\r\n              <small>{{ 'account.trustedPurchase' | translate }}</small>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </aside>\r\n\r\n      <!-- Form panel -->\r\n      <section class=\"form-panel\">\r\n        <div class=\"mobile-brand avalamooz-brand\">\r\n          <div class=\"mobile-brand-logo avalamooz-logo-frame\">\r\n            <img width=\"144\" height=\"44\" class=\"avalamooz-logo\" src=\"./assets/learning/brand/logo.png\" [alt]=\"'brand.name' | translate\" />\r\n            <span class=\"brand-sparkle\" aria-hidden=\"true\">✦</span>\r\n          </div>\r\n          <div class=\"mobile-brand-info\">\r\n            <strong>{{ 'brand.name' | translate }}</strong>\r\n            <span>{{ 'account.academy' | translate }}</span>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"form-wrap\">\r\n          <div class=\"form-heading\">\r\n            <div class=\"heading-icon\">\r\n              <ion-icon [name]=\"modeIcon\"></ion-icon>\r\n            </div>\r\n            <div class=\"heading-texts\">\r\n              <span class=\"form-kicker\">{{ modeKicker }}</span>\r\n              <h2>{{ modeTitle }}</h2>\r\n              <p>{{ modeDescription }}</p>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Primary Mode Switcher (Login / Register) -->\r\n          <div class=\"mode-switch\" *ngIf=\"isPrimaryMode\">\r\n            <button\r\n              type=\"button\"\r\n              class=\"switch-btn\"\r\n              [class.active]=\"selectedMode === modes[0]\"\r\n              (click)=\"onLogin()\">\r\n              <ion-icon name=\"log-in-outline\"></ion-icon>\r\n              <span>{{ 'account.signIn' | translate }}</span>\r\n            </button>\r\n            <button\r\n              type=\"button\"\r\n              class=\"switch-btn\"\r\n              [class.active]=\"selectedMode === modes[1]\"\r\n              (click)=\"onRegister()\">\r\n              <ion-icon name=\"person-add-outline\"></ion-icon>\r\n              <span>{{ 'account.freeSignup' | translate }}</span>\r\n            </button>\r\n          </div>\r\n\r\n          <!-- Google Quick Auth Button -->\r\n          <button\r\n            type=\"button\"\r\n            class=\"google-button\"\r\n            *ngIf=\"(selectedMode === modes[0] || selectedMode === modes[1]) && !isMobile\"\r\n            [disabled]=\"googleBusy\" (click)=\"onGoogle()\">\r\n            <img src=\"./assets/images/google-icon.svg\" alt=\"Google\" width=\"20\" height=\"20\" />\r\n            <span>{{ (selectedMode === modes[0] ? 'account.googleLogin' : 'account.googleSignup') | translate }}</span>\r\n          </button>\r\n\r\n          <!-- Divider -->\r\n          <div class=\"divider\" *ngIf=\"(selectedMode === modes[0] || selectedMode === modes[1]) && !isMobile\">\r\n            <span>{{ 'account.continueEmail' | translate }}</span>\r\n          </div>\r\n\r\n          <!-- Child Auth Forms Container -->\r\n          <div class=\"auth-form\">\r\n            <app-login *ngIf=\"selectedMode === modes[0]\"></app-login>\r\n            <app-buyer-register *ngIf=\"selectedMode === modes[1]\"></app-buyer-register>\r\n            <app-seller-register *ngIf=\"selectedMode === modes[2]\"></app-seller-register>\r\n            <app-teacher-register *ngIf=\"selectedMode === modes[3]\"></app-teacher-register>\r\n            <app-admin-register *ngIf=\"selectedMode === modes[4]\"></app-admin-register>\r\n            <app-forget-password *ngIf=\"selectedMode === modes[5]\"></app-forget-password>\r\n            <app-reset-password [email]=\"email\" [id]=\"id\" *ngIf=\"selectedMode === modes[6]\"></app-reset-password>\r\n            <app-two-factor [email]=\"email\" [id]=\"id\" *ngIf=\"selectedMode === modes[7]\"></app-two-factor>\r\n            <app-invite [inviteId]=\"id\" *ngIf=\"selectedMode === modes[8]\"></app-invite>\r\n          </div>\r\n\r\n          <!-- Bottom Actions for Login -->\r\n          <div class=\"form-actions\" *ngIf=\"selectedMode === modes[0]\">\r\n            <button type=\"button\" class=\"text-action forgot-link\" (click)=\"onForgetPassword()\">\r\n              <ion-icon name=\"help-circle-outline\"></ion-icon>\r\n              <span>{{ 'account.forgotPassword' | translate }}</span>\r\n            </button>\r\n            <div class=\"switch-prompt\">\r\n              <span>{{ 'account.notMember' | translate }}</span>\r\n              <button type=\"button\" class=\"prompt-btn\" (click)=\"onRegister()\">\r\n                {{ 'account.createFree' | translate }}\r\n              </button>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Bottom Actions for Register and Forget Password -->\r\n          <div class=\"form-actions centered\" *ngIf=\"selectedMode === modes[1] || selectedMode === modes[5]\">\r\n            <div class=\"switch-prompt\">\r\n              <span>{{ 'account.haveAccount' | translate }}</span>\r\n              <button type=\"button\" class=\"prompt-btn\" (click)=\"onLogin()\">\r\n                {{ 'account.signIn' | translate }}\r\n              </button>\r\n            </div>\r\n          </div>\r\n\r\n          <!-- Back to Login Button for auxiliary modes -->\r\n          <button\r\n            class=\"back-action\"\r\n            type=\"button\"\r\n            *ngIf=\"!isPrimaryMode && selectedMode !== modes[5]\"\r\n            (click)=\"onLogin()\">\r\n            <ion-icon name=\"arrow-forward-outline\"></ion-icon>\r\n            <span>{{ 'account.backToLogin' | translate }}</span>\r\n          </button>\r\n\r\n          <!-- Security Trust Badge -->\r\n          <div class=\"trust-note\">\r\n            <ion-icon name=\"shield-checkmark-outline\"></ion-icon>\r\n            <span>{{ 'account.secureConnection' | translate }}</span>\r\n          </div>\r\n        </div>\r\n      </section>\r\n    </section>\r\n  </main>\r\n</ion-content>\r\n";

